using SmartInventoryArrange.Core;
int checks=0;void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}
var vertical=new ShapeMask(new[]{new Cell(0,0),new Cell(0,1)});var horizontal=new ShapeMask(new[]{new Cell(0,0),new Cell(1,0)});
var items=Enumerable.Range(0,6).Select(n=>new LayoutItem{StableId=$"synthetic-{n}",ItemId=$"token-{n%2}",PrimaryCategory="MATERIAL",Categories=new[]{"MATERIAL"},Orientations=new[]{new Orientation(0,vertical,false),new Orientation(1,horizontal,true)},OriginalMask=vertical,OriginalX=(n%3)*2,OriginalY=(n/3)*3,OriginalOrientation=0}).ToArray();
LayoutProblem Make(LayoutItem[] entries)=>new(){Width=6,Height=5,Usable=new bool[,]{{true,true,true,true,true},{true,true,true,true,true},{true,true,true,true,true},{true,true,true,true,true},{true,true,true,true,true},{true,true,true,true,true}},Items=entries};
var p=Make(items);var original=items.Select(i=>new Placement(i.StableId,i.OriginalX,i.OriginalY,0,vertical,i.PrimaryCategory,false)).ToArray();
using var ctl=new GlobalArrangeController();var req=ctl.Begin(p,original,"synthetic-container:state1");var first=req.Session.Advance(31,10000);Check(req.Restarted,"initial restart");Check(Native34Solver.ValidateLayout(p,first.Result.Placements),"first legal");ctl.Complete(req,p,first.Result.Placements);
var again=ctl.Begin(p,first.Result.Placements,"synthetic-container:state1");Check(!again.Restarted&&ReferenceEquals(req.Session,again.Session),"same actual session");var second=again.Session.Advance(31,10000);Check(second.NewNodes>0&&second.TotalNodes>first.TotalNodes,"new nodes");Check(second.TotalCandidates>=first.TotalCandidates,"candidates retained");ctl.Complete(again,p,second.Result.Placements);
var remaining=items.Take(4).ToArray();var p2=Make(remaining);var q2=second.Result.Placements.Where(q=>remaining.Any(i=>i.StableId==q.StableId)).ToArray();var removal=ctl.Begin(p2,q2,"synthetic-container:state1");Check(removal.Restarted&&!ReferenceEquals(req.Session,removal.Session)&&removal.Session.TotalNodes==0,"removal resets");var result=removal.Session.Advance(31,10000);Check(Native34Solver.ValidateLayout(p2,result.Result.Placements)&&result.Result.Placements.Count==4,"survivors preserved");ctl.Complete(removal,p2,result.Result.Placements);
using var one=new Native34Solver().CreateSession(p,original);using var two=new Native34Solver().CreateSession(p,original);one.Advance(31,1000000);var split=one.Advance(31,1000000);var whole=two.Advance(62,1000000);Check(split.TotalNodes==whole.TotalNodes,"segmented nodes");Check(split.TotalCandidates==whole.TotalCandidates,"segmented candidates");Check(Native34Solver.SameLayout(split.Result.Placements,whole.Result.Placements),"segmented coordinates");
var changed=ctl.Begin(p2,result.Result.Placements,"synthetic-container:state2");Check(changed.Restarted,"state resets");ctl.Reset();bool stale=false;try{ctl.Complete(changed,p2,result.Result.Placements);}catch(InvalidOperationException){stale=true;}Check(stale,"stale completion rejected");
Console.WriteLine($"SESSION checks={checks}/{checks} actualFrontier=True removalReset=True deterministic=True exit=0");
